window.MG_LAZY_DATA["data/lazy/resources/security-v26-036-50833a34863d4c33.json"]={sha256:"50833a34863d4c332ee34d33e45835add1443267cdff0427321033a05c855086",value:{"sources":[{"id":"v26-case-94d24d89e444f14b","url":"https://schema.ocsf.io/","title":"Open Cybersecurity Schema Framework","titleEn":"Open Cybersecurity Schema Framework","publisher":"OCSF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-036","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-036","related":[{"id":"security-v26-037","referenceUrls":["https://d3fend.mitre.org/"],"title":"MITRE D3FEND：防禦技術、數位物件與證據圖","titleEn":"MITRE D3FEND: countermeasures, artifacts and evidence graphs","why":"用兩課的可觀察驗收條件比較模型邊界：85%與95%可追溯原始列，剩餘未知狀態保留；不以跨產品統一欄位宣稱偵測能力已相同。 交付三產品映射契約、240筆品質統計及版本遷移差異。","whyEn":"Compare model boundaries using observable acceptance criteria: Trace 85% and 95% to raw rows, preserve unknown states and do not infer equal detection capability from shared field names. Deliver three mapping contracts, 240-event quality statistics and version-migration differences.","difference":"為本機教學服務挑六項防禦動作與四類觀測物件；每條關係寫輸入證據、可觀察轉換與限制，不只貼技術標籤。","differenceEn":"Select six defensive actions and four artifact types for a local teaching service; record input evidence, observable transformation and limits for each relationship.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["語義完整率=所有必填且可解釋欄位通過的事件/總事件；JSON語法有效與schema有效、語義正確是三層不同判定。 合成240事件中，204筆通過必填欄位、型別與狀態語義驗證，36筆隔離。 204/240×100=85%；修正24筆後228/240×100=95%。","本地關係矩陣覆蓋=已以fixture驗證的指定關係/預先定義關係；知識圖譜存在一條邊不代表你的產品已有效實作。 教學驗收定義24條需驗證關係，其中18條有可重現證據。 18/24×100=75%；再驗證3條後21/24×100=87.5%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Semantic completeness is events with all required interpretable fields divided by total events; valid JSON, valid schema and correct meaning are distinct checks. Of 240 synthetic events, 204 pass required-field, type and status-semantics checks, with 36 quarantined. 204/240×100=85%; correcting 24 yields 228/240×100=95%.","Local matrix coverage is fixture-validated relationships divided by predefined relationships; an ontology edge does not prove effective implementation in a product. The teaching acceptance plan defines 24 relationships, of which 18 have reproducible evidence. 18/24×100=75%; validating three more gives 21/24×100=87.5%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-046","referenceUrls":["https://support.apple.com/guide/deployment/intro-to-filevault-dep82064ec40/1/web/1.0","https://support.apple.com/guide/security/hardware-security-overview-secf020d1074/web"],"title":"Apple FileVault：開機保護與復原金鑰治理","titleEn":"Apple FileVault: boot protection and recovery-key governance","why":"用兩課的可觀察驗收條件比較模型邊界：85%與95%可追溯原始列，剩餘未知狀態保留；不以跨產品統一欄位宣稱偵測能力已相同。 交付三產品映射契約、240筆品質統計及版本遷移差異。","whyEn":"Compare model boundaries using observable acceptance criteria: Trace 85% and 95% to raw rows, preserve unknown states and do not infer equal detection capability from shared field names. Deliver three mapping contracts, 240-event quality statistics and version-migration differences.","difference":"為虛構Mac資產分列平台類型、FileVault狀態、核准使用者與復原金鑰託管驗證；不要把硬體本身的儲存加密當成已啟用使用者保護。","differenceEn":"Separate platform type, FileVault state, authorized users and recovery escrow verification for fictional Macs; do not equate inherent hardware storage encryption with enabled user protection.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["語義完整率=所有必填且可解釋欄位通過的事件/總事件；JSON語法有效與schema有效、語義正確是三層不同判定。 合成240事件中，204筆通過必填欄位、型別與狀態語義驗證，36筆隔離。 204/240×100=85%；修正24筆後228/240×100=95%。","可驗證管理覆蓋=同時符合加密政策與復原託管證據的裝置/範圍裝置；兩者缺一都不能算完整。 200台教學Mac中180台同時具政策與託管驗證，其餘20台缺一項。 180/200×100=90%；補修10台後190/200×100=95%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Semantic completeness is events with all required interpretable fields divided by total events; valid JSON, valid schema and correct meaning are distinct checks. Of 240 synthetic events, 204 pass required-field, type and status-semantics checks, with 36 quarantined. 204/240×100=85%; correcting 24 yields 228/240×100=95%.","Verified management coverage is devices meeting both encryption policy and recovery-escrow evidence divided by in-scope devices; either missing part is incomplete. Of 200 teaching Macs, 180 have both policy and escrow evidence and 20 lack one requirement. 180/200×100=90%; completing ten yields 190/200×100=95%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-88dd19746c477a96","url":"https://d3fend.mitre.org/","title":"MITRE D3FEND Matrix","titleEn":"MITRE D3FEND Matrix","publisher":"MITRE","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-d225c9ae6a5805c0","url":"https://support.apple.com/guide/deployment/intro-to-filevault-dep82064ec40/1/web/1.0","title":"Apple: Intro to FileVault","titleEn":"Apple: Intro to FileVault","publisher":"Apple","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-2e81006c3bcff072","url":"https://support.apple.com/guide/security/hardware-security-overview-secf020d1074/web","title":"Apple Platform Security: Hardware security overview","titleEn":"Apple Platform Security: Hardware security overview","publisher":"Apple","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
